mapper.select:
SELECT fp.product_id, fp.brokerage_id, b.brokerage_name, fp.product_type, fp.product_name, fp.description, fp.nav, fp.maturity_date, fp.launch_date FROM financial_product fp JOIN brokerage b ON fp.brokerage_id = b.brokerage_id
AND fp.brokerage_id = #{brokerageId}
AND fp.product_type = #{productType}
ORDER BY b.brokerage_id, fp.product_id
